-- Existing students, clocks and prior paper versions are untouched.
begin;
insert into academy_tcf_listening.papers(id,version,content)
values('tcf-listening-11','tcf-listening-2026-11-test11-v1',$paper11${"id":"tcf-listening-11","version":"tcf-listening-2026-11-test11-v1","title":"TCF Listening · Test 11","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La scène représente une personne assise, occupée à consulter un petit télescope.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un petit télescope à une table. D. Elle court sur un terrain de sport.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un petit télescope à une table. D. Elle court sur un terrain de sport."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.071,"slotSeconds":33},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Un homme présente une affiche liée à sciences et recherche.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il peint une façade extérieure. B. Il présente une affiche sur sciences et recherche à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il peint une façade extérieure. B. Il présente une affiche sur sciences et recherche à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.618,"slotSeconds":32},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Deux interlocuteurs préparent une fête de la science autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes préparent une fête de la science autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes préparent une fête de la science autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.093,"slotSeconds":35},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'illustration montre une personne portant un sac devant le centre scientifique de Montpellier.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant le centre scientifique de Montpellier.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant le centre scientifique de Montpellier."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.454,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier d'observation des étoiles ?\nA. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier d'observation des étoiles ?"},{"voice":"female","text":"A. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos."}],"audio":"q-05.mp3","audioSeconds":19.191,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un petit télescope pour participer à une fête de la science ?\nA. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un petit télescope pour participer à une fête de la science ?"},{"voice":"female","text":"A. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail."}],"audio":"q-06.mp3","audioSeconds":19.197,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier d'observation des étoiles ?\nA. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier d'observation des étoiles ?"},{"voice":"female","text":"A. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat."}],"audio":"q-07.mp3","audioSeconds":17.676,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une fête de la science. Est-ce possible ?\nA. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une fête de la science. Est-ce possible ?"},{"voice":"female","text":"A. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau."}],"audio":"q-08.mp3","audioSeconds":21.101,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["une hausse générale des tarifs","la fermeture définitive du lieu","l'ouverture d'un laboratoire aux visiteurs le jeudi","la suppression de toutes les activités"],"correct":"C","explanation":"L'annonce présente précisément l'ouverture d'un laboratoire aux visiteurs le jeudi sans annoncer de fermeture ni d'augmentation.","transcript":"Question 9.\nInformation aux visiteurs. Dans le centre scientifique de Montpellier, à compter de lundi prochain, nous mettons en place l'ouverture d'un laboratoire aux visiteurs le jeudi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans le centre scientifique de Montpellier, à compter de lundi prochain, nous mettons en place l'ouverture d'un laboratoire aux visiteurs le jeudi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.937,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["L'inscription exige un paiement supplémentaire.","L'une des personnes ne peut pas arriver à l'heure initiale.","Le bâtiment vient d'être vendu.","Les deux personnes ont décidé d'annuler l'activité."],"correct":"B","explanation":"Le rendez-vous est décalé parce qu'une réunion empêche une arrivée à l'heure.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier d'observation des étoiles ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier d'observation des étoiles ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.75,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["En remplissant un formulaire sur le site avant jeudi.","En payant directement sur place le jour même.","En envoyant un courrier postal au responsable.","En téléphonant uniquement le dimanche matin."],"correct":"A","explanation":"L'inscription se fait en ligne avant jeudi et donne lieu à une confirmation.","transcript":"Question 11.\nUne rencontre autour de sciences et recherche aura lieu dans le centre scientifique de Montpellier. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre autour de sciences et recherche aura lieu dans le centre scientifique de Montpellier. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.282,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Quitter définitivement l'événement.","Reprendre toute la procédure de paiement.","Attendre une réponse par la poste.","Montrer sa confirmation à l'accueil."],"correct":"D","explanation":"Le responsable demande le message de confirmation pour retrouver le dossier.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier d'observation des étoiles, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier d'observation des étoiles, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.874,"slotSeconds":42},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance est supprimée pour toute la saison.","Tous les participants doivent s'inscrire à nouveau.","Le début de la séance est reporté d'une heure.","L'activité change de ville."],"correct":"C","explanation":"L'annonce ne modifie que l'heure de début, de quatorze à quinze heures.","transcript":"Question 13.\nMessage aux participants de un atelier d'observation des étoiles. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants de un atelier d'observation des étoiles. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.483,"slotSeconds":38},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Déplacer la rencontre dans une autre région.","Maintenir la présentation et envoyer la démonstration plus tard.","Annuler définitivement l'activité sans prévenir.","Remplacer les participants par une autre équipe."],"correct":"B","explanation":"Ils maintiennent une partie de l'activité et prévoient un complément ultérieur.","transcript":"Question 14.\nLe matériel destiné à un atelier d'observation des étoiles n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier d'observation des étoiles n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.45,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Un nouveau dispositif répond à un besoin, mais ses limites restent à évaluer.","Le service est fermé définitivement depuis plusieurs années.","Toutes les difficultés ont été résolues immédiatement.","Les habitants n'ont pas été informés du changement."],"correct":"A","explanation":"Le reportage expose l'objectif du dispositif, une contrainte persistante et un bilan à venir.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre scientifique de Montpellier : l'ouverture d'un laboratoire aux visiteurs le jeudi. Le dispositif vise à répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Plusieurs représentants soulignent toutefois que certaines observations restent impossibles par mauvais temps. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre scientifique de Montpellier : l'ouverture d'un laboratoire aux visiteurs le jeudi. Le dispositif vise à répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Plusieurs représentants soulignent toutefois que certaines observations restent impossibles par mauvais temps. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":33.501,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Pour supprimer toutes les permanences de l'après-midi.","Parce qu'un événement a été déplacé à l'étranger.","Pour modifier le prix des inscriptions.","Pour garantir une présence à l'accueil toute la journée."],"correct":"D","explanation":"Les collègues se relaient afin que personne ne trouve l'accueil fermé.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme de sciences participatives.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme de sciences participatives."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.19,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Aux visiteurs ayant déjà terminé toutes les démarches.","Exclusivement aux responsables politiques.","Aux personnes qui éprouvent des difficultés d'accès au service habituel.","Uniquement aux salariés de l'équipe d'accueil."],"correct":"C","explanation":"Le message vise les usagers dont l'accès au service habituel est difficile.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans le centre scientifique de Montpellier. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans le centre scientifique de Montpellier. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":32.096,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Le responsable a refusé toutes les réservations.","Elle ne sera pas disponible à l'heure initialement proposée.","L'établissement a perdu son paiement.","Elle a décidé d'abandonner l'événement."],"correct":"B","explanation":"La personne travaille vendredi et choisit un horaire compatible.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une fête de la science. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une fête de la science. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.335,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Pour favoriser les échanges et les questions.","Parce que la visite est réservée aux professionnels.","Parce que toutes les salles ont été fermées.","Pour demander davantage de frais aux visiteurs."],"correct":"A","explanation":"La limite vise à faciliter l'interaction avec l'animateur.","transcript":"Question 19.\nÀ l'occasion de une fête de la science, des visites en petits groupes seront proposées dans le centre scientifique de Montpellier. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"À l'occasion de une fête de la science, des visites en petits groupes seront proposées dans le centre scientifique de Montpellier. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.549,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle trouve le prix trop élevé.","Elle ne connaît pas le lieu de rendez-vous.","Elle veut reporter une réservation de transport.","Elle souhaite obtenir des garanties sur la qualité des données issues d'observations irrégulières."],"correct":"D","explanation":"Elle juge les horaires adaptés mais souhaite éclaircir la question de la qualité des données issues d'observations irrégulières.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la qualité des données issues d'observations irrégulières. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la qualité des données issues d'observations irrégulières. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":29.985,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Pour annuler les activités prévues après midi.","Pour demander le paiement anticipé d’une inscription.","Pour répartir les équipes selon les besoins des différents créneaux.","Pour sélectionner uniquement les personnes ayant déjà travaillé dans le secteur."],"correct":"C","explanation":"Les organisateurs veulent équilibrer les effectifs tout au long de la journée.","transcript":"Question 21.\nAnnonce locale. Dans le centre scientifique de Montpellier, à l’occasion de une fête de la science, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans le centre scientifique de Montpellier, à l’occasion de une fête de la science, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.38,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["L’obligation de poursuivre l’activité chaque semaine.","Les échanges durables et les liens de confiance entre les participants.","Le gain financier assuré dès la première séance.","La disparition complète des difficultés d’organisation."],"correct":"B","explanation":"L’invitée insiste sur les liens humains et les idées partagées plutôt que sur un bénéfice immédiat.","transcript":"Question 22.\nVous participez à un atelier d'observation des étoiles. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier d'observation des étoiles. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":47.039,"slotSeconds":64},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Tester la solution, consulter les personnes concernées et publier un bilan.","Appliquer définitivement le projet sans recueillir d’avis.","Supprimer les réunions publiques et toutes les mesures.","Attendre que les désaccords disparaissent spontanément."],"correct":"A","explanation":"Le compromis consiste en une expérimentation limitée, évaluée et ouverte aux retours.","transcript":"Question 23.\nVous écoutez une table ronde consacrée à sciences et recherche.\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des explications publiques des méthodes et des données.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde consacrée à sciences et recherche."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des explications publiques des méthodes et des données."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":56.121,"slotSeconds":73},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["Les enquêteurs ont choisi un questionnaire trop long pour être imprimé.","Les résultats portent sur une activité qui n’existe plus.","Les personnes interrogées ont toutes répondu dans plusieurs langues.","L'enquête interroge surtout les utilisateurs présents et ignore les personnes écartées du service."],"correct":"D","explanation":"Les personnes ayant abandonné le service ne sont pas représentées dans l’enquête.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le programme de sciences participatives. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le programme de sciences participatives. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.9,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["L’absence complète d’obstacles techniques et sociaux.","Une décision de remplacer les responsables par des visiteurs.","Le besoin d'améliorer le service sans négliger les effets sur d'autres usagers.","La volonté unanime de supprimer toute activité dans la région."],"correct":"C","explanation":"Le reportage oppose l’objectif d’amélioration aux préoccupations concrètes des personnes affectées.","transcript":"Question 25.\nVous regardez un reportage régional. Dans le centre scientifique de Montpellier, une initiative propose des explications publiques des méthodes et des données. Les responsables espèrent ainsi répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude.\nNous soutenons l’objectif général, mais il faut prendre en compte la qualité des données issues d'observations irrégulières. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que maintenir le suivi scientifique et rendre les résultats compréhensibles. Pourtant, certaines observations restent impossibles par mauvais temps. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans le centre scientifique de Montpellier, une initiative propose des explications publiques des méthodes et des données. Les responsables espèrent ainsi répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la qualité des données issues d'observations irrégulières. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que maintenir le suivi scientifique et rendre les résultats compréhensibles. Pourtant, certaines observations restent impossibles par mauvais temps. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":56.118,"slotSeconds":73},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["La responsable souhaite désormais éviter de rencontrer les usagers.","Les premiers résultats sont encourageants, mais le suivi à long terme reste insuffisant.","Le service n’a jamais accueilli le moindre participant.","Toutes les étapes du projet ont été abandonnées avant le lancement."],"correct":"B","explanation":"Elle souligne la persistance de difficultés et l’absence de recul sur les résultats.","transcript":"Question 26.\nVous avez lancé l'ouverture d'un laboratoire aux visiteurs le jeudi. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certaines observations restent impossibles par mauvais temps. Et nous n’avons pas encore assez de recul pour mesurer la reproductibilité des observations recueillies. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé l'ouverture d'un laboratoire aux visiteurs le jeudi. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certaines observations restent impossibles par mauvais temps. Et nous n’avons pas encore assez de recul pour mesurer la reproductibilité des observations recueillies. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":46.818,"slotSeconds":63},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Améliorer l'accès le matin tout en maintenant une possibilité de visite en soirée.","Fermer le service chaque après-midi pour réduire les coûts.","Interdire aux utilisateurs de changer leurs rendez-vous.","Réserver le dispositif aux employés travaillant tôt."],"correct":"A","explanation":"Ils cherchent à répondre aux besoins de deux catégories d’usagers, pas à en exclure une.","transcript":"Question 27.\nPlusieurs personnes demandent que le programme de sciences participatives ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le programme de sciences participatives ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.354,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Avoir consacré trop de temps à rencontrer des usagers très différents.","Avoir demandé une évaluation du service après son ouverture.","Avoir supprimé toutes les dépenses de matériel dès le départ.","Avoir choisi les solutions avant de comprendre les besoins des utilisateurs."],"correct":"D","explanation":"L’experte critique une conception descendante sans consultation préalable.","transcript":"Question 28.\nLe projet de une station de mesures partagée a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la qualité des données issues d'observations irrégulières est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de une station de mesures partagée a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la qualité des données issues d'observations irrégulières est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":49.454,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["Les invités défendent tous deux le remplacement des résultats par des opinions.","Le débat oppose deux lieux sans rapport avec l’évaluation.","L'un privilégie les indicateurs chiffrés, l'autre réclame aussi des observations qualitatives.","L’un souhaite interdire toute mesure, l’autre veut supprimer les témoignages."],"correct":"C","explanation":"L’opposition porte sur l’importance relative des chiffres et des observations de terrain.","transcript":"Question 29.\nVous écoutez un débat consacré à sciences et recherche.\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions mesurer la reproductibilité des observations recueillies et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré à sciences et recherche."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions mesurer la reproductibilité des observations recueillies et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":50.001,"slotSeconds":67},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Transformer nécessairement chaque site en commerce privé.","Conserver les traces significatives tout en permettant des usages adaptés aux besoins actuels.","Interdire chaque modification, même mineure, pour toujours.","Effacer toutes les traces historiques avant de réutiliser le lieu."],"correct":"B","explanation":"L’invitée défend une conservation compatible avec l’évolution des usages.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier d'observation des étoiles, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier d'observation des étoiles, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.601,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Confronter les prévisions d’un modèle aux observations réelles.","Considérer les hypothèses initiales comme des certitudes immuables.","Choisir systématiquement le modèle qui annonce les meilleurs résultats.","Remplacer toute expérience de terrain par une simulation unique."],"correct":"A","explanation":"La conférencière recommande de confronter les prévisions d’un modèle aux observations réelles.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la reproductibilité des observations recueillies. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la reproductibilité des observations recueillies. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":57.452,"slotSeconds":74},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Présenter une prédiction unique comme absolument certaine.","Renoncer à communiquer toute information tant que les résultats ne sont pas parfaits.","Mettre sur le même plan toutes les estimations, indépendamment des preuves.","Expliquer les hypothèses, les marges d'incertitude et les conditions de révision."],"correct":"D","explanation":"Elle défend une communication transparente sur les limites et la robustesse des prévisions.","transcript":"Question 32.\nVous avancez des projections concernant le programme de sciences participatives, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le programme de sciences participatives, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.188,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["Les données chiffrées ne peuvent jamais apporter d’information utile.","L’évaluation doit porter exclusivement sur le coût du matériel.","Le nombre de visiteurs ou de participants ne suffit pas à mesurer les bénéfices réels.","La hausse de fréquentation prouve à elle seule le succès de toutes les mesures."],"correct":"C","explanation":"La chroniqueuse distingue un indicateur de fréquentation et une véritable mesure des effets.","transcript":"Question 33.\nDans le centre scientifique de Montpellier, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'ouverture d'un laboratoire aux visiteurs le jeudi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la reproductibilité des observations recueillies ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans le centre scientifique de Montpellier, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'ouverture d'un laboratoire aux visiteurs le jeudi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la reproductibilité des observations recueillies ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":47.026,"slotSeconds":65},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Limiter toute consultation aux personnes ayant conçu le dispositif.","Tester le service avec divers usagers et conserver une aide humaine accessible.","Supprimer tous les guichets avant d'étudier les difficultés.","Considérer que le nombre de connexions mesure à lui seul la réussite."],"correct":"B","explanation":"Les intervenants conviennent d’associer les usagers à l’évaluation et de maintenir une assistance.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans le centre scientifique de Montpellier.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment la question de la qualité des données issues d'observations irrégulières.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans le centre scientifique de Montpellier."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment la question de la qualité des données issues d'observations irrégulières."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":53.231,"slotSeconds":71},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Un équipement performant sur le papier garantit automatiquement un résultat sur le terrain.","Les usages réels et l’entretien influencent les résultats obtenus.","Une étude de terrain peut conduire à modifier une installation.","Les utilisateurs ont parfois besoin d’explications adaptées."],"correct":"A","explanation":"L’invitée conteste précisément l’idée que la performance technique suffise à garantir l’efficacité réelle.","transcript":"Question 35.\nLe dispositif que vous avez installé dans l'observatoire de la colline affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans l'observatoire de la colline affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.295,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Lorsque tous les participants sont obligés d’assister à chaque réunion.","Lorsque les organisateurs imposent les mêmes rôles à toutes les générations.","Lorsque le seul critère retenu est le nombre de présences.","Lorsque chacun peut choisir ses activités et participer librement."],"correct":"D","explanation":"L’invitée met l’accent sur le volontariat, le choix et la réciprocité.","transcript":"Question 36.\nVotre initiative autour de un atelier d'observation des étoiles réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également veiller à la qualité des données issues d'observations irrégulières. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier d'observation des étoiles réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également veiller à la qualité des données issues d'observations irrégulières. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":52.025,"slotSeconds":70},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Parce qu’il faut éviter de vérifier les dates et les décisions.","Parce que la version la plus émouvante doit toujours être retenue.","Leurs différences révèlent des points de vue qu'il faut confronter aux faits vérifiables.","Parce que toutes les affirmations contradictoires sont nécessairement exactes."],"correct":"C","explanation":"Elle distingue les faits vérifiables des expériences vécues et situe les témoignages dans leur contexte.","transcript":"Question 37.\nDans votre étude concernant le programme de sciences participatives, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le programme de sciences participatives, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":54.423,"slotSeconds":72},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le seul enjeu est de rendre la communication plus spectaculaire.","Une initiative populaire peut fragiliser les conditions mêmes de sa réussite.","Une forte fréquentation garantit toujours la durabilité d’un projet.","La prudence exige de refuser toute expérimentation nouvelle."],"correct":"B","explanation":"L’exposé souligne le risque de confondre popularité immédiate et progrès durable.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du domaine de sciences et recherche.  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, l'ouverture d'un laboratoire aux visiteurs le jeudi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la qualité des données issues d'observations irrégulières. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du domaine de sciences et recherche.  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, l'ouverture d'un laboratoire aux visiteurs le jeudi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la qualité des données issues d'observations irrégulières. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":65.602,"slotSeconds":83},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Prévoir des ressources durables, répartir les responsabilités et évaluer les effets réels.","Prolonger indéfiniment l’effort exceptionnel des premiers bénévoles.","Considérer la fréquentation initiale comme une garantie suffisante de financement.","Supprimer toute évaluation afin d’accélérer la croissance."],"correct":"A","explanation":"L’invitée insiste sur la viabilité financière et humaine, ainsi que sur le suivi à long terme.","transcript":"Question 39.\nVotre programme, qui concerne le programme de sciences participatives, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certaines observations restent impossibles par mauvais temps. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la reproductibilité des observations recueillies. L’idée n’est pas d’abandonner l’ambition de départ : maintenir le suivi scientifique et rendre les résultats compréhensibles. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre programme, qui concerne le programme de sciences participatives, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certaines observations restent impossibles par mauvais temps. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la reproductibilité des observations recueillies. L’idée n’est pas d’abandonner l’ambition de départ : maintenir le suivi scientifique et rendre les résultats compréhensibles. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":64.123,"slotSeconds":82}]}$paper11$::jsonb)
on conflict(id,version) do nothing;
do $$begin
 if not exists(select 1 from academy_tcf_listening.papers
  where id='tcf-listening-11' and version='tcf-listening-2026-11-test11-v1'
    and content->>'seconds'='2100'
    and jsonb_array_length(content->'questions')=39)
 then raise exception 'Complete paper missing';end if;
 if exists(select 1 from academy_tcf_listening.published
  where test_id='tcf-listening-11' and version<>'tcf-listening-2026-11-test11-v1')
 then raise exception 'Another listening version is already active';end if;
